function Modal({title,subtitle,children,onClose,wide=false}){
 const ref=useRef();
 useEffect(()=>{const previous=document.activeElement;ref.current?.focus();const key=e=>{if(e.key==='Escape')onClose();if(e.key==='Tab'){const els=[...ref.current.querySelectorAll('button,input,textarea,select,a[href],[tabindex="0"]')].filter(el=>!el.disabled);if(!els.length)return;let first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}};document.addEventListener('keydown',key);return()=>{document.removeEventListener('keydown',key);previous?.focus()};},[onClose]);
 return <div className="modal-shade" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><section className={'window '+(wide?'wide':'')} ref={ref} role="dialog" aria-modal="true" aria-labelledby="dialog-title" tabIndex={-1}><header className="window-head"><div><h2 id="dialog-title">{title}</h2>{subtitle&&<p>{subtitle}</p>}</div><button className="icon-button" aria-label="关闭窗口" onClick={onClose}><Icon name="close"/></button></header>{children}</section></div>
}
function Notice({children,kind='info'}){return <div className={'notice '+kind} role={kind==='error'?'alert':'status'}>{children}</div>}
function Submit({busy,children,...props}){return <button className="primary" disabled={busy} {...props}>{busy?<><span className="spinner"/>正在处理…</>:children}</button>}
function Field({label,children,hint}){return <label className="field"><span>{label}</span>{children}{hint&&<small>{hint}</small>}</label>}
function Badge({status}){return <span className={'status '+status}>{statusLabels[status]||status}</span>}
function FilePicker({onFiles}){const [error,setError]=useState('');return <><label className="file-drop"><Icon name="file"/><span>带来一份资料 <small>TXT / Markdown，最多 3 份，每份 14,000 字符</small></span><input type="file" accept=".txt,.md" multiple onChange={async e=>{try{const files=await Promise.all([...e.target.files].map(readFile));onFiles(files);setError('')}catch(err){setError(err.message)}e.target.value=''}}/></label>{error&&<Notice kind="error">{error}</Notice>}</>}

